head.script:

        var count=0;

		scwin.trigger1_onclick = function(e) {

			var bFormatter = function () {
			    return [
			        {
			            'id' : 'custombtn',
			            'className' : 'w2widget_btnCustom',
						'ariaLabel' : '커스텀버튼1',
						'title' : '커스텀버튼1',
			            'isCustom' : true
			        },
			        {
			            'id' : 'custombtn2',
			            'className' : 'w2widget_btnCustom',
						'ariaLabel' : '커스텀버튼2',
						'title' : '커스텀버튼2',
						'ariaLabelLocaleRef' : 'widget_btn_aria_label',
						'titleLocaleRef' : 'widget_btn_title',
			            'isCustom' : true
			        },
			        {'useDefault' : 'maximize'},
			        {'useDefault' : 'close'}
			    ];
			};

			count++;
			widgetContainer1.addWidgets({
			    id : "widget"+count,
			    title : "위젯"+count,
			    src : "widgetContainer_buttonFormatter_WESD-1717_(WSQ-5773).xml",
			    scope : true,
			    x : 0,
			    y : 0,
			    unitWidth : 1,
			    unitHeight : 1,
			    buttonFormatter : bFormatter
			});
		};

	scwin.widgetContainer_onclickcustombtn = function(widgetId,btnId) {

		alert("위젯아이디 : "+widgetId+"\n"+"버튼아이디 : "+btnId);

		if(widgetId == "mf_widgetContainer1_widget1"){
		mf_widgetContainer1_widget1.toggleMaximized();
		}
	};

		scwin.checkVal = function() {
			return WebSquare.wUnit.getDomById('widgetContainer1_widget1_title_custombtn2').getAttribute('title') == 'global_undefined';
		}	

		scwin.unitTest = function(){
			//init
			WebSquare.wUnit.start();
			WebSquare.wUnit.addCommand("pause", "500");		
			WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
			WebSquare.wUnit.addCommand("pause", "500");	
			WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
			WebSquare.wUnit.addCommand("pause", "500");		

			//Run  and stop
			WebSquare.wUnit.run();
			WebSquare.wUnit.stop();
		}
		scwin.unitTest();
